import{_ as t,c as s,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"易附录纂注卷十一","description":"易附录纂注 - 易附录纂注卷十一","frontmatter":{"title":"易附录纂注卷十一","description":"易附录纂注 - 易附录纂注卷十一"},"headers":[],"relativePath":"zh/classics/yifulu-zuanzhu/012.md","filePath":"zh/classics/yifulu-zuanzhu/012.md"}'),r={name:"zh/classics/yifulu-zuanzhu/012.md"};function i(c,a,o,u,d,p){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易附录纂注卷十一",tabindex:"-1"},[n("易附录纂注卷十一 "),e("a",{class:"header-anchor",href:"#易附录纂注卷十一","aria-label":"Permalink to “易附录纂注卷十一”"},"​")],-1),e("p",null,"钦定四库全书",-1),e("p",null,"元胡一桂撰总论序卦 问：「序卦，或谓非圣人之书，信乎？」曰：「此沙随程氏之说也。先懦以为非圣人之缊，某以为谓之非易之精则可，谓非易之缊则不可。周子分精与缊字甚分明。序卦却正是易之缊，事事夹杂，有在里面。」问：「何谓易之精？」曰：「如易有太极，精是生两仪，两仪生四象，四象生八卦，这便是易之问。如序卦中亦见消长进退之义，唤做不是精不得。」曰：「此正是事事夹杂，有在里面，正是缊。须是自一个生出来，以至于无穷，便是精。」道夫。 纂注 程子曰：乾、坤，天地之道，阴阳之本，故为上篇之首。坎、离，阴阳之成质，故为上篇之终。咸、恒，夫妇之道，生育之本，故为下篇之首。未济，坎、离之合；既济，坎、离之交，合而交，则生物，阴阳之功也，故为下篇之终。二篇之卦既分，而后推其义而为之次，序卦是也。",-1),e("p",null,"有天地，然后万物生焉。盈天地之间者唯万物，故受之以屯；屯者，盈也；屯者，物之始生也。物生必蒙，故受之以蒙；蒙者，蒙也，物之稚也。物稚不可不养也，故受之以需；需者，饮食之道也。饮食必有讼，故受之以讼。讼必有众起，故受之以师；师者，众也。众必有所比，故受之以比；比者，比也。比必有所畜，故受之以小畜。物畜然后有礼，故受之以履。履而泰，然后安，故受之以泰； 晁氏云：郑无「而泰」二字。 「泰」者，通也。物不可以终通，故受之以否。物不可以终否，故受之以同人。与人同者，物必归焉，故受之以大有。有大者不可以盈，故受之以谦。有大而能谦必豫，故受之以豫。豫必有随，故受之以随。以喜随人者必有事，故受之以蛊；蛊者，事也。有事而后可大，故受之以临；临者，大也。物大然后可观，故受之以观。可观而后有所合，故受之以「噬嗑」。嗑者，合也。物不可以苟合而已，故受之以贲。贲者，饰也。致饰然后亨则尽矣，故受之以剥。剥者，剥也。物不可以终尽，剥穷上反下，故受之以复。复则不妄矣，故受之以「无妄」。有无妄然后可畜，故受之以大畜。物畜然后可养，故受之以颐。颐者，养也。不养则不可动，故受之以大过。附录。 问：不养则不可动，故受之以大过，何也？曰：动则过矣，故小过亦曰：「有其信者必行之，故受之以小过」。道夫 物不可以终过，故受之以坎。坎者，陷也。陷必有所丽，故受之以离。离者，丽也。 右上篇。 有天地然后有万物，有万物然后有男女，有男女然后有夫妇，有夫妇然后有父子，有父子然后有君臣，有君臣然后有上下，有上下然后礼义有所错。附录。 问：「序卦中六十四卦独不言咸，何也？」曰：「夫妇之道即咸也。」曰：「亦如上经不言乾、坤，但言天地，则乾、坤可见否？」曰：「然。」道夫。 夫妇之道，不可以不久也，故受之以恒，恒者，久也。物不可以久居其所，故受之以遁，遁者，退也。物不可以终遁，故受之以大壮。物不可以终壮，故受之以晋。附录。 问：「物不可以终壮，故受之以晋。传曰：物无壮而终止之理，既壮盛则必进。窃意物进而后至于壮盛，既壮盛则衰退继之矣。今曰壮盛则必进，此义如何？」曰：「物固有壮而后进者，亦有进而后壮者，其义自有不同。此各随其事而言，难以一说拘也。且以十二月卦论，大壮之为夬，夬之为乾，岂非壮而后进乎？至乾乃极而衰耳。」又问：「壮与晋何别？」曰：「不但如此壮而已，又更须进一步也。」道夫。 晋者，进也。进必有所伤，故受之以明夷，夷者，伤也。伤于外者，必反其家，故受之以家人。家道穷必乖，故受之以「睽」，睽者，乖也。乖必有难，故受之以「蹇」，蹇者，难也。物不可以终难，故受之以「解」；解者，缓也。缓必有所失。附录。 问：「缓」字恐不是迟缓之「缓」，乃是懈怠之意，故曰：「解，缓也」。曰：「缓」字是散意。道夫。 故受之以「损」。损而不已必益，故受之以「益」。益而不已必决，故受之以「夬」；夬者，决也。决必有所遇，故受之以「姤」；姤者，遇也。物相遇而后聚，故受之以「萃」；萃者，聚也。聚而上者谓之升，故受之以「升」。升而不已必困，故受之以「困」。困乎上者必反下，故受之以「井」。井道不可不革，故受之以「革」。革物者莫若鼎，故受之以「鼎」。主器者莫若长子，故受之以「震」；震者，动也。物不可以终动，止之，故受之以「艮」；艮者，止也。物不可以终止，故受之以「渐」；渐者，进也。进必有所归，故受之以「归妹」。得其所归者必大，故受之以「丰」；丰者，大也。穷大者必失其居，故受之以「旅」。旅而无所容，故受之以「巽」；巽者，入也。入而后说之，故受之以「兑」；兑者，说也。说而后散之，故受之以「涣」，涣者，离也。物不可以终离，故受之以「节」。节而信之，故受之以「中孚」。有其信者必行之，故受之以「小过」。有过物者必济，故受之以既济。物不可穷也，故受之以未济终焉。 右下篇 易附录纂注卷十一。",-1)])])}const m=t(r,[["render",i]]);export{h as __pageData,m as default};
